"use client";

import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { SparklesIcon, XIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { AnswerCard } from "./ai-search-bar/answer-card";
import {
  KINDS,
  RECENT,
  type SearchRecord,
  SUGGESTED,
  searchRecords,
} from "./ai-search-bar/data";
import { Highlight } from "./ai-search-bar/highlight";
import { ClockIcon, SearchIcon } from "./icons";
import { useTicker } from "./lib/use-ticker";
import { countAllWords, revealParts } from "./lib/words";

const ANSWER_TICKS = 40;

type Option =
  | { key: string; type: "ask"; label: string }
  | { key: string; type: "recent" | "suggest"; label: string }
  | { key: string; type: "result"; record: SearchRecord };

/** The options the list shows for a query, in the order the arrow keys walk them. */
function optionsFor(query: string, results: SearchRecord[]): Option[] {
  if (!query.trim()) {
    return [
      ...RECENT.map((label) => ({
        key: `recent-${label}`,
        type: "recent" as const,
        label,
      })),
      ...SUGGESTED.map((label) => ({
        key: `suggest-${label}`,
        type: "suggest" as const,
        label,
      })),
    ];
  }
  return [
    { key: "ask", type: "ask", label: query.trim() },
    ...results.map((record) => ({
      key: record.id,
      type: "result" as const,
      record,
    })),
  ];
}

/** The answer for a query: an opening line, then one cited sentence for each of the first two results. */
function answerFor(query: string, results: SearchRecord[]) {
  const cited = results.slice(0, 2);
  const intro =
    results.length === 0
      ? `Nothing in Fernhill matches "${query.trim()}" yet. Try a patient's surname or a room.`
      : `${results.length === 1 ? "One record matches" : `${results.length} records match`} "${query.trim()}".`;
  return { cited, parts: [intro, ...cited.map((record) => record.answer)] };
}

/**
 * A search card for the clinic app. Results update on every keystroke, grouped
 * by kind with the match marked. Ask Fernhill, the first row, streams a short
 * answer whose numbered citations point at the results below.
 */
export function AiSearchBar({ className }: { className?: string }) {
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const [asked, setAsked] = useState<string | null>(null);
  const [opened, setOpened] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const listId = useId();
  const titleId = useId();
  const inputRef = useRef<HTMLInputElement>(null);

  const results = searchRecords(query);
  const options = optionsFor(query, results);
  const activeIndex = Math.min(active, options.length - 1);
  const activeOption = options[activeIndex];
  const answer = asked === null ? null : answerFor(asked, searchRecords(asked));
  // A fixed limit, longer than any answer, so a reduced-motion start shows the whole reply at once.
  const stream = useTicker(ANSWER_TICKS, 70);
  const shown = answer ? revealParts(answer.parts, stream.tick * 2) : [];
  const streaming =
    answer !== null &&
    stream.running &&
    stream.tick * 2 < countAllWords(answer.parts);

  useEffect(() => {
    if (!activeOption) return;
    document
      .getElementById(`${listId}-${activeOption.key}`)
      ?.scrollIntoView({ block: "nearest" });
  }, [activeOption, listId]);

  const type = (value: string) => {
    setQuery(value);
    setActive(0);
    setOpened(null);
  };

  const ask = (text: string) => {
    setAsked(text);
    setCopied(false);
    stream.start();
  };

  const choose = (option: Option) => {
    if (option.type === "ask") ask(option.label);
    else if (option.type === "result") setOpened(option.record.title);
    else type(option.label);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    const count = options.length;
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      if (count === 0) return;
      setActive(
        (activeIndex + (event.key === "ArrowDown" ? 1 : -1) + count) % count,
      );
    } else if (event.key === "Enter" && activeOption) {
      event.preventDefault();
      choose(activeOption);
    } else if (event.key === "Escape") {
      if (asked !== null) setAsked(null);
      else type("");
    }
  };

  const cite = (id: string) => {
    const index = options.findIndex((option) => option.key === id);
    if (index >= 0) setActive(index);
    inputRef.current?.focus();
  };

  const copy = () => {
    if (!answer) return;
    void navigator.clipboard
      ?.writeText(answer.parts.join(" "))
      .catch(() => undefined);
    setCopied(true);
  };

  const groups = query.trim()
    ? KINDS.map((kind) => ({
        id: kind.id,
        label: kind.group,
        items: options.filter(
          (option) =>
            option.type === "result" && option.record.kind === kind.id,
        ),
      }))
    : [
        {
          id: "recent",
          label: "Recent",
          items: options.filter((option) => option.type === "recent"),
        },
        {
          id: "suggest",
          label: "Try",
          items: options.filter((option) => option.type === "suggest"),
        },
      ];

  const row = (option: Option) => {
    const selected = option === activeOption;
    return (
      <div
        key={option.key}
        id={`${listId}-${option.key}`}
        role="option"
        aria-selected={selected}
        onPointerDown={(event) => event.preventDefault()}
        onPointerMove={() => setActive(options.indexOf(option))}
        onClick={() => choose(option)}
        className={cn(
          "flex min-h-11 cursor-pointer items-center gap-3 rounded-lg px-3 py-2 text-sm",
          selected ? "bg-muted" : undefined,
        )}
      >
        {option.type === "ask" ? (
          <>
            <SparklesIcon
              aria-hidden="true"
              className="size-4 shrink-0 text-chart-4"
            />
            <span className="min-w-0 flex-1 truncate">
              Ask Fernhill about{" "}
              <span className="font-medium">&ldquo;{option.label}&rdquo;</span>
            </span>
            <kbd className="hidden rounded border border-border px-1.5 text-xs text-muted-foreground @sm:inline">
              Enter
            </kbd>
          </>
        ) : option.type === "result" ? (
          <>
            <span className="flex min-w-0 flex-1 flex-col">
              <span className="truncate font-medium">
                <Highlight text={option.record.title} query={query} />
              </span>
              <span className="truncate text-xs text-muted-foreground">
                <Highlight text={option.record.detail} query={query} />
              </span>
            </span>
            <span
              className={cn(
                "shrink-0 rounded-full px-2 py-0.5 text-xs font-medium",
                KINDS.find((kind) => kind.id === option.record.kind)?.tint,
              )}
            >
              {KINDS.find((kind) => kind.id === option.record.kind)?.label}
            </span>
          </>
        ) : (
          <>
            {option.type === "recent" ? (
              <ClockIcon
                aria-hidden="true"
                className="size-4 shrink-0 text-muted-foreground"
              />
            ) : (
              <SearchIcon
                aria-hidden="true"
                className="size-4 shrink-0 text-muted-foreground"
              />
            )}
            <span className="truncate">{option.label}</span>
          </>
        )}
      </div>
    );
  };

  const askOption = options.find((option) => option.type === "ask");

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <h2 id={titleId} className="sr-only">
        Search Fernhill
      </h2>
      <div className="flex items-center gap-2 border-b border-border px-4 py-3">
        <SearchIcon
          aria-hidden="true"
          className="size-4 shrink-0 text-muted-foreground"
        />
        <Input
          ref={inputRef}
          role="combobox"
          aria-expanded="true"
          aria-controls={listId}
          aria-activedescendant={
            activeOption ? `${listId}-${activeOption.key}` : undefined
          }
          aria-autocomplete="list"
          aria-label="Search patients, bookings and guides"
          placeholder="Search patients, bookings and guides"
          value={query}
          onChange={(event) => type(event.target.value)}
          onKeyDown={onKeyDown}
          className="min-w-0 flex-1"
        />
        {query ? (
          <Button
            variant="ghost"
            size="icon"
            className="size-8"
            aria-label="Clear search"
            onClick={() => {
              type("");
              inputRef.current?.focus();
            }}
          >
            <XIcon aria-hidden="true" className="size-4" />
          </Button>
        ) : null}
      </div>

      <div className="scroll-fade-effect-y scrollbar-none h-104 overflow-y-auto overscroll-contain py-2">
        {answer && asked !== null ? (
          <AnswerCard
            parts={answer.parts}
            shown={shown}
            cited={answer.cited}
            streaming={streaming}
            copied={copied}
            onCite={cite}
            onCopy={copy}
            onClose={() => setAsked(null)}
          />
        ) : null}
        <div
          id={listId}
          role="listbox"
          aria-label="Results"
          className="flex flex-col gap-2 px-2"
        >
          {askOption ? row(askOption) : null}
          {groups.map((group) =>
            group.items.length > 0 ? (
              <div
                key={group.id}
                role="group"
                aria-labelledby={`${listId}-${group.id}`}
                className="flex flex-col"
              >
                <span
                  id={`${listId}-${group.id}`}
                  role="presentation"
                  className="px-3 pt-1 pb-1 text-xs font-medium text-muted-foreground"
                >
                  {group.label}
                </span>
                {group.items.map(row)}
              </div>
            ) : null,
          )}
          {query.trim() && results.length === 0 ? (
            <p className="px-3 py-6 text-center text-sm text-muted-foreground">
              No records match. Ask Fernhill instead.
            </p>
          ) : null}
        </div>
      </div>

      <p
        role="status"
        className="truncate border-t border-border px-4 py-2.5 text-xs text-muted-foreground"
      >
        {opened
          ? `Opened ${opened}`
          : query.trim()
            ? `${results.length} results`
            : "Arrows move, Enter opens, Escape clears"}
      </p>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

