import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import { SparklesIcon, XIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";

import { CopyIcon } from "../icons";
import type { SearchRecord } from "./data";

/** Props for the short answer above the results. */
export interface AnswerCardProps {
  /** The opening line, then one sentence per cited record. */
  parts: string[];
  /** The same parts, cut to what has streamed so far. */
  shown: string[];
  cited: SearchRecord[];
  streaming: boolean;
  copied: boolean;
  onCite: (id: string) => void;
  onCopy: () => void;
  onClose: () => void;
}

/**
 * A short written answer with numbered citations. Each number moves the
 * result list to the record it cites. The text streams in; screen readers
 * hear it once, when it is complete.
 */
export function AnswerCard({
  parts,
  shown,
  cited,
  streaming,
  copied,
  onCite,
  onCopy,
  onClose,
}: AnswerCardProps) {
  const complete = !streaming;
  return (
    <section
      aria-label="Answer"
      aria-busy={streaming}
      className="mx-2 mb-2 rounded-xl border border-border p-3"
    >
      <div className="flex items-start gap-2.5">
        {/* A box one text line tall centres the icon on the first line, with no nudge. */}
        <span className="flex h-5 shrink-0 items-center">
          <SparklesIcon
            aria-hidden="true"
            className="size-4 shrink-0 text-chart-4"
          />
        </span>
        <p
          aria-live="polite"
          className="min-w-0 flex-1 text-sm leading-relaxed"
        >
          <span aria-hidden={!complete}>
            {shown.map((text, index) => {
              const record = index === 0 ? null : cited[index - 1];
              const done = text === parts[index];
              return (
                <span key={record?.id ?? "intro"}>
                  {text}
                  {record && done ? (
                    <Button
                      variant="outline"
                      size="sm"
                      className="mx-1 h-5 min-w-5 align-text-top"
                      aria-label={`Source ${index}: ${record.title}`}
                      onClick={() => onCite(record.id)}
                    >
                      <span className="px-1.5 text-xs">{index}</span>
                    </Button>
                  ) : null}{" "}
                </span>
              );
            })}
          </span>
        </p>
        <div className="flex shrink-0 gap-0.5">
          <Button
            variant="ghost"
            size="icon"
            className="size-7"
            aria-label={copied ? "Answer copied" : "Copy answer"}
            disabled={streaming}
            onClick={onCopy}
          >
            <CopyIcon aria-hidden="true" className="size-3.5" />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            className="size-7"
            aria-label="Close answer"
            onClick={onClose}
          >
            <XIcon aria-hidden="true" className="size-3.5" />
          </Button>
        </div>
      </div>
    </section>
  );
}

